package com.eliteexiles.companion;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class EliteExilesCompanionPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(EliteExilesCompanionPlugin.class);
        RuneLite.main(args);
    }
}

package com.eliteexiles.companion;

import org.junit.Assert;
import org.junit.Test;

public class BridgeUrlMigrationTest
{
    @Test
    public void preservesValidHttpsOrigins()
    {
        Assert.assertFalse(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(
            EliteExilesCompanionConfig.PRODUCTION_BRIDGE_URL));
        Assert.assertFalse(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(
            "https://coach.example.com"));
        Assert.assertFalse(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(
            "https://coach.example.com/"));
        Assert.assertFalse(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(
            "https://coach.example.com:443"));
    }

    @Test
    public void migratesBlankLegacyAndUnsafeValues()
    {
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(null));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(""));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl(" "));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("http://127.0.0.1:47621"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("http://localhost:47621"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("E9XU7ANY"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("http://coach.example.com"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("ftp://coach.example.com"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("https://user:pass@coach.example.com"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("https://coach.example.com/path"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("https://coach.example.com/?q=1"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("https://coach.example.com/#fragment"));
        Assert.assertTrue(EliteExilesCompanionPlugin.shouldMigrateBridgeUrl("https://coach.example.com:8443"));
    }
}

package com.eliteexiles.companion;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(EliteExilesCompanionConfig.GROUP)
public interface EliteExilesCompanionConfig extends Config
{
    String GROUP = "eliteexilescompanion";
    String PRODUCTION_BRIDGE_URL = "https://elite-exiles-coach.tail0d6194.ts.net";

    @ConfigItem(
        keyName = "coachIntegration",
        name = "Enable Elite Exiles Sync",
        description = "Optional Elite Exiles connection. OFF by default. Linking sends your OSRS display name and one-time Discord link code. Once linked, Companion access does not depend on Discord roles, staff approval, or current clan membership. Qualifying native OSRS clan system broadcasts may be sent to build the shared clan activity feed; optional Live session sync sends skill levels/XP, total XP, session XP, and session start time for progression, SOTW, rank/emblem context, and clan features. Ordinary clan chat messages are never sent. No Elite Exiles network requests are made while this setting is disabled.",
        warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
        position = 0
    )
    default boolean coachIntegration()
    {
        return false;
    }

    @ConfigItem(
        keyName = "bridgeUrl",
        name = "Elite Exiles bridge URL",
        description = "Elite Exiles production clan endpoint. Managed automatically for normal Plugin Hub users.",
        hidden = true,
        position = 1
    )
    default String bridgeUrl()
    {
        return PRODUCTION_BRIDGE_URL;
    }

    @ConfigItem(
        keyName = "autoSync",
        name = "Live session sync",
        description = "When Elite Exiles Sync is enabled and linked, send your current RSN, skill levels/XP, total XP, session XP and session start time for synced progression and clan competition. This is optional and does not award EE Points by itself.",
        position = 2
    )
    default boolean autoSync()
    {
        return false;
    }

    @ConfigItem(
        keyName = "refreshSeconds",
        name = "HQ refresh seconds",
        description = "How often optional Elite Exiles Sync refreshes HQ. Values below 60 seconds are treated as 60.",
        position = 3
    )
    default int refreshSeconds()
    {
        return 90;
    }
}

package com.eliteexiles.companion;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.net.URI;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.swing.SwingUtilities;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ChatInput;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Elite Exiles Companion",
    description = "Exile HQ: local session tracking plus optional Elite Exiles progression, GROUP finder, SOTW competition, EE progression, Pet Hunt status and clan events.",
    tags = {"clan", "progression", "discord", "lfg", "competition", "sotw", "stats", "qol"}
)
public class EliteExilesCompanionPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ChatCommandManager chatCommandManager;
    @Inject private EliteExilesBridgeClient bridge;
    @Inject private EliteExilesCompanionConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ScheduledExecutorService scheduler;

    private EliteExilesPanel panel;
    private NavigationButton navButton;
    private ScheduledFuture<?> backgroundTask;
    private final Map<String, LiveSkill> liveSkills = new ConcurrentHashMap<>();
    private volatile String currentRsn;
    private volatile long sessionStartedAt;
    private volatile long sessionStartXp;
    private volatile long currentTotalXp;
    private volatile boolean pendingLoginInit;
    private volatile long lastDashboardPull;
    private volatile long lastLivePush;
    private volatile long lastUiRefresh;
    private volatile boolean dashboardPullInFlight;
    private volatile int bridgeProtocol;
    private static final String GROUP_COMMAND = "!group";
    private static final long ACTIVE_UI_REFRESH_MS = 30_000L;
    private static final long LIVE_PUSH_INTERVAL_MS = 60_000L;
    private static final int BACKGROUND_TICK_SECONDS = 30;

    @Provides
    EliteExilesCompanionConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(EliteExilesCompanionConfig.class);
    }

    @Override
    protected void startUp()
    {
        migrateBridgeUrl();
        panel = new EliteExilesPanel();
        panel.setController(this);
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        navButton = NavigationButton.builder()
            .tooltip("Elite Exiles • Exile HQ")
            .icon(icon)
            .priority(8)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);
        chatCommandManager.registerCommand(GROUP_COMMAND, (message, value) -> { }, this::groupCommandInput);

        bridgeProtocol = 0;
        if (coachEnabled())
        {
            if (bridge.isLinked())
            {
                panel.setBusy("Connecting Exile HQ…");
                pullDashboard();
            }
            else panel.setDisconnected("Elite Exiles Sync is enabled. Join Discord, run /runelitelink, then paste the code above.");
        }
        else panel.setLocalMode();

        pendingLoginInit = client.getGameState() == GameState.LOGGED_IN;
        // Login/stat events drive visible session changes. Background work only maintains
        // optional server sync, so keep it slow and use fixed delay to avoid task bunching.
        backgroundTask = scheduler.scheduleWithFixedDelay(
            this::backgroundTick, 10, BACKGROUND_TICK_SECONDS, TimeUnit.SECONDS);
    }

    private void migrateBridgeUrl()
    {
        String saved = configManager.getConfiguration(EliteExilesCompanionConfig.GROUP, "bridgeUrl");
        if (shouldMigrateBridgeUrl(saved))
            configManager.setConfiguration(EliteExilesCompanionConfig.GROUP, "bridgeUrl", EliteExilesCompanionConfig.PRODUCTION_BRIDGE_URL);
    }

    static boolean shouldMigrateBridgeUrl(String value) { return !isValidHttpsBridgeOrigin(value); }

    static boolean isValidHttpsBridgeOrigin(String value)
    {
        if (value == null || value.isBlank()) return false;
        try
        {
            String trimmed = value.trim();
            while (trimmed.endsWith("/")) trimmed = trimmed.substring(0, trimmed.length() - 1);
            URI uri = URI.create(trimmed);
            String scheme = uri.getScheme() == null ? "" : uri.getScheme().toLowerCase(Locale.ROOT);
            String host = uri.getHost() == null ? "" : uri.getHost().toLowerCase(Locale.ROOT);
            if (!"https".equals(scheme) || host.isBlank()) return false;
            if (uri.getUserInfo() != null || uri.getQuery() != null || uri.getFragment() != null) return false;
            String path = uri.getPath();
            if (path != null && !path.isBlank() && !"/".equals(path)) return false;
            return uri.getPort() == -1 || uri.getPort() == 443;
        }
        catch (IllegalArgumentException ex) { return false; }
    }

    @Override
    protected void shutDown()
    {
        if (backgroundTask != null) { backgroundTask.cancel(true); backgroundTask = null; }
        chatCommandManager.unregisterCommand(GROUP_COMMAND);
        if (navButton != null) { clientToolbar.removeNavigation(navButton); navButton = null; }
        liveSkills.clear();
        panel = null;
        currentRsn = null;
        bridgeProtocol = 0;
        dashboardPullInFlight = false;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN) pendingLoginInit = true;
        else if (event.getGameState() == GameState.LOGIN_SCREEN) pendingLoginInit = false;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!pendingLoginInit) return;
        Player local = client.getLocalPlayer();
        if (local == null || local.getName() == null || local.getName().isBlank()) return;
        String name = local.getName();
        boolean changedAccount = currentRsn == null || !normalize(currentRsn).equals(normalize(name));
        currentRsn = name;
        currentTotalXp = client.getOverallExperience();
        if (changedAccount || sessionStartedAt == 0L)
        {
            sessionStartedAt = System.currentTimeMillis();
            sessionStartXp = currentTotalXp;
            liveSkills.clear();
        }
        for (Skill skill : Skill.values())
        {
            try { liveSkills.put(skillLabel(skill), new LiveSkill(client.getRealSkillLevel(skill), client.getSkillExperience(skill))); }
            catch (Exception ignored) { }
        }
        pendingLoginInit = false;
        if (panel != null)
        {
            lastUiRefresh = System.currentTimeMillis();
            panel.updateLiveSnapshot(currentRsn, Math.max(0L, currentTotalXp - sessionStartXp), snapshotLevels());
            // RuneLite can switch to the logged-in character's configuration
            // profile after this plugin has already started. Re-read the sync
            // setting here so the link controls do not remain stuck in the
            // pre-login LOCAL MODE state.
            if (!coachEnabled())
            {
                bridgeProtocol = 0;
                panel.setLocalMode();
            }
            else if (bridge.isLinked())
            {
                bridgeProtocol = 0;
                panel.setBusy("Connecting Exile HQ…");
            }
            else
            {
                panel.setDisconnected("Elite Exiles Sync is enabled. Join Discord, run /runelitelink, then paste the code above.");
            }

        }
        if (coachEnabled() && bridge.isLinked())
        {
            pushLive();
            pullDashboard();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() == null) return;
        liveSkills.put(skillLabel(event.getSkill()), new LiveSkill(event.getLevel(), event.getXp()));
        try { currentTotalXp = client.getOverallExperience(); } catch (Exception ignored) { }
        long now = System.currentTimeMillis();
        if (panel != null && now - lastUiRefresh >= ACTIVE_UI_REFRESH_MS)
        {
            lastUiRefresh = now;
            panel.updateLiveSnapshot(currentRsn, Math.max(0L, currentTotalXp - sessionStartXp), snapshotLevels());
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event == null || event.getType() == null) return;
        if (event.getType() == ChatMessageType.CLAN_CHAT)
        {
            applyEliteExilesChatStyle(event);
            return;
        }
        if (event.getType() != ChatMessageType.CLAN_MESSAGE) return;
        if (!coachEnabled() || !bridge.isLinked() || !supportsExileHqProtocol()) return;
        String plain = Text.removeTags(event.getMessage() == null ? "" : event.getMessage()).replaceAll("\\s+", " ").trim();
        if (!isPotentialClanActivity(plain)) return;
        bridge.sendClanBroadcast(plain, ignored -> { }, ignored -> { });
    }

    private void applyEliteExilesChatStyle(ChatMessage event)
    {
        if (!coachEnabled() || !bridge.isLinked() || event.getMessageNode() == null) return;

        // Local-only, minimal identity treatment: keep RuneLite/Jagex username and
        // message rendering completely native and only tint the existing Elite Exiles
        // clan-channel label. Ordinary clan conversation is never uploaded.
        String sender = event.getMessageNode().getSender();
        if (!"eliteexiles".equals(normalize(Text.removeTags(sender == null ? "" : sender)))) return;
        event.getMessageNode().setSender("<col=8f00ff>Elite Exiles</col>");
        client.refreshChat();
    }

    private static boolean isPotentialClanActivity(String message)
    {
        String lower = message == null ? "" : message.toLowerCase(Locale.ROOT);
        return lower.contains("received") || lower.contains("obtained") || lower.contains("drop") || lower.contains("loot")
            || lower.contains("pet") || lower.contains("collection log") || lower.contains("combat task")
            || lower.contains("combat achievement") || lower.contains("personal best") || lower.contains("quest")
            || lower.contains("level") || lower.contains("player kill") || lower.contains("pked") || lower.contains("killed by");
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!EliteExilesCompanionConfig.GROUP.equals(event.getGroup()) || panel == null) return;
        if (!coachEnabled()) { bridgeProtocol = 0; panel.setLocalMode(); return; }
        if (bridge.isLinked()) { bridgeProtocol = 0; panel.setBusy("Connecting Exile HQ…"); pullDashboard(); }
        else panel.setDisconnected("Elite Exiles Sync is enabled. Join Discord, run /runelitelink, then paste the code above.");
    }

    void linkFromPanel(String code)
    {
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (currentRsn == null || currentRsn.isBlank()) { panel.setError("Log into the OSRS account you registered in Discord first."); return; }
        String cleanedCode = code == null ? "" : code.toUpperCase().replaceAll("[^A-HJ-NP-Z2-9]", "");
        if (cleanedCode.length() != 8) { panel.setError("That link code is not 8 valid characters. Run /runelitelink and paste the fresh code."); return; }
        panel.setBusy("Checking Elite Exiles bridge…");
        bridge.health(health -> {
            if (!isExpectedHealth(health)) { handleBridgeError("Bridge health response did not match the Elite Exiles protocol."); return; }
            updateBridgeProtocol(health);
            bridge.link(cleanedCode, currentRsn, response -> {
                updateBridgeProtocol(response);
                if (panel != null) panel.updateDashboard(response);
                pushLive();
            }, this::handleBridgeError);
        }, this::handleBridgeError);
    }

    void refreshProgressionFromPanel()
    {
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (!bridge.isLinked()) { panel.setDisconnected("Use /runelitelink in Discord to connect."); return; }
        if (!supportsExileHqProtocol()) { panel.setError(protocolUpgradeMessage()); return; }
        panel.setBusy("Refreshing Jagex + Elite Exiles progression…");
        bridge.refreshProgression(response -> { if (panel != null) panel.updateDashboard(response); }, this::handleBridgeError);
    }

    void hostGroupFromPanel(String activity, int world)
    {
        if (!coachEnabled()) { if (panel != null) panel.setLocalMode(); return; }
        if (!bridge.isLinked()) { if (panel != null) panel.setDisconnected("Use /runelitelink in Discord to connect."); return; }
        if (!supportsExileHqProtocol()) { if (panel != null) panel.setError(protocolUpgradeMessage()); return; }
        if (panel != null) panel.setBusy("Hosting Elite Exiles group…");
        bridge.hostGroup(activity, world,
            response -> { if (panel != null) panel.updateDashboard(response); },
            message -> { if (panel != null) { panel.setError(message); panel.hostGroupButton.setEnabled(true); } });
    }

    void joinGroupFromPanel(String groupId)
    {
        if (!supportsExileHqProtocol()) { if (panel != null) panel.setError(protocolUpgradeMessage()); return; }
        if (panel != null) panel.setBusy("Joining clan group…");
        bridge.joinGroup(groupId, response -> { if (panel != null) panel.updateDashboard(response); }, this::handleBridgeError);
    }

    void startGroupFromPanel(String groupId)
    {
        if (!supportsExileHqProtocol()) { if (panel != null) panel.setError(protocolUpgradeMessage()); return; }
        if (panel != null) panel.setBusy("Starting clan group…");
        bridge.startGroup(groupId, response -> { if (panel != null) panel.updateDashboard(response); }, this::handleBridgeError);
    }

    void leaveGroupFromPanel(String groupId)
    {
        if (!supportsExileHqProtocol()) { if (panel != null) panel.setError(protocolUpgradeMessage()); return; }
        if (panel != null) panel.setBusy("Updating clan group…");
        bridge.leaveGroup(groupId, response -> { if (panel != null) panel.updateDashboard(response); }, this::handleBridgeError);
    }

    void completeGroupFromPanel(String groupId)
    {
        if (!supportsExileHqProtocol()) { if (panel != null) panel.setError(protocolUpgradeMessage()); return; }
        if (panel != null) panel.setBusy("Confirming GROUP completion…");
        bridge.completeGroup(groupId, this::applyDashboardResponse, this::handleBridgeError);
    }

    private boolean groupCommandInput(ChatInput input, String value)
    {
        SwingUtilities.invokeLater(() -> {
            if (navButton != null) clientToolbar.openPanel(navButton);
            if (panel != null) panel.openGroupPage();
        });
        // The local !group command opens the GROUP page and is consumed by RuneLite.
        return true;
    }

    void checkInFromPanel()
    {
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (!bridge.isLinked()) { panel.setDisconnected("Use /runelitelink in Discord to connect."); return; }
        if (!supportsExileHqProtocol()) { panel.setError(protocolUpgradeMessage()); return; }
        panel.setBusy("Verifying goals + missions…");
        pushLive();
        bridge.checkIn(response -> { if (panel != null) panel.showCheckinResult(response); }, this::handleBridgeError);
    }

    void runDiagnosticsFromPanel()
    {
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (!bridge.isLinked()) { panel.setDisconnected("Link Elite Exiles first."); return; }
        if (currentRsn == null || currentRsn.isBlank()) { panel.setError("Log into the linked OSRS account before running diagnostics."); return; }
        final long started = System.nanoTime();
        final String nonce = "ee-" + Long.toUnsignedString(System.nanoTime(), 36);
        panel.setBusy("Running safe diagnostics…");
        bridge.health(health -> {
            if (!isExpectedHealth(health)) { handleBridgeError("Bridge health response did not match the Elite Exiles protocol."); return; }
            bridge.diagnostics(diagnostic -> {
                if (!isSafeDiagnosticResponse(diagnostic)) { handleBridgeError("Authenticated diagnostics failed the no-mutation safety contract."); return; }
                if (!normalize(currentRsn).equals(normalize(stringValue(diagnostic, "rsn")))) { handleBridgeError("Diagnostic RSN did not match the logged-in RuneLite account."); return; }
                bridge.diagnosticsEcho(nonce, echo -> {
                    if (!isSafeDiagnosticResponse(echo) || !nonce.equals(stringValue(echo, "echo"))) { handleBridgeError("Diagnostic POST/JSON echo failed."); return; }
                    long elapsedMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started);
                    if (panel != null) panel.showDiagnosticsResult(stringValue(diagnostic, "bridgeId"), intValue(diagnostic, "protocol", 0), elapsedMs);
                }, this::handleBridgeError);
            }, this::handleBridgeError);
        }, this::handleBridgeError);
    }

    void unlinkFromPanel()
    {
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (!bridge.isLinked()) { panel.setDisconnected("Already unlinked."); return; }
        panel.setBusy("Revoking Companion link…");
        bridge.unlink(response -> { bridgeProtocol = 0; if (panel != null) panel.setDisconnected("Link revoked. Use /runelitelink to reconnect."); }, this::handleBridgeError);
    }

    private void backgroundTick()
    {
        if (panel == null) return;
        long now = System.currentTimeMillis();
        if (!coachEnabled() || !bridge.isLinked()) return;
        int refreshSeconds = Math.max(60, config.refreshSeconds());
        if (config.autoSync() && currentRsn != null && now - lastLivePush >= LIVE_PUSH_INTERVAL_MS) pushLive();
        if (now - lastDashboardPull >= refreshSeconds * 1000L) pullDashboard();
    }


    private void pullDashboard()
    {
        if (!coachEnabled() || !bridge.isLinked() || dashboardPullInFlight) return;
        dashboardPullInFlight = true;
        lastDashboardPull = System.currentTimeMillis();
        bridge.getDashboard(
            response -> {
                dashboardPullInFlight = false;
                applyDashboardResponse(response);
            },
            message -> {
                dashboardPullInFlight = false;
                handleBridgeError(message);
            });
    }

    private void applyDashboardResponse(JsonObject response)
    {
        updateBridgeProtocol(response);
        if (panel != null) panel.updateDashboard(response);
    }

    private void pushLive()
    {
        if (!coachEnabled() || !config.autoSync() || !bridge.isLinked() || currentRsn == null || currentRsn.isBlank()) return;
        lastLivePush = System.currentTimeMillis();
        JsonObject body = new JsonObject();
        body.addProperty("rsn", currentRsn);
        body.addProperty("sessionStartedAt", sessionStartedAt);
        body.addProperty("totalXp", currentTotalXp);
        body.addProperty("sessionXp", Math.max(0L, currentTotalXp - sessionStartXp));
        JsonArray skills = new JsonArray();
        for (Map.Entry<String, LiveSkill> entry : liveSkills.entrySet())
        {
            JsonObject row = new JsonObject();
            row.addProperty("name", entry.getKey());
            row.addProperty("level", entry.getValue().level);
            row.addProperty("xp", entry.getValue().xp);
            skills.add(row);
        }
        body.add("skills", skills);
        bridge.sendLive(body, ignored -> { }, this::handleBridgeError);
    }

    private Map<String, Integer> snapshotLevels()
    {
        Map<String, Integer> out = new LinkedHashMap<>();
        for (Map.Entry<String, LiveSkill> entry : liveSkills.entrySet()) out.put(entry.getKey(), entry.getValue().level);
        return out;
    }

    private void updateBridgeProtocol(JsonObject response)
    {
        if (response == null) return;
        int protocol = intValue(response, "protocol", 0);
        if (protocol <= 0 && response.has("dashboard") && response.get("dashboard").isJsonObject())
            protocol = intValue(response.getAsJsonObject("dashboard"), "protocol", 0);
        if (protocol > 0) bridgeProtocol = protocol;
    }

    private boolean supportsExileHqProtocol()
    {
        return bridgeProtocol >= 6;
    }

    private String protocolUpgradeMessage()
    {
        return bridgeProtocol > 0
            ? "HQ / GROUP / COMPETE features need bridge protocol 6; the connected bridge is protocol " + bridgeProtocol + ". Refresh again after the server update."
            : "Exile HQ is still confirming the Elite Exiles bridge version. Wait a moment and refresh before using this feature.";
    }

    private void handleBridgeError(String message)
    {
        if (panel == null) return;
        if (!coachEnabled()) { panel.setLocalMode(); return; }
        if (!bridge.isLinked()) panel.setDisconnected(message + " Generate a new code with /runelitelink.");
        else panel.setError(message);
    }

    private boolean coachEnabled() { return config != null && config.coachIntegration(); }

    private static boolean isExpectedHealth(JsonObject response)
    {
        return response != null && booleanValue(response, "ok", false)
            && "elite-exiles-runelite-bridge".equals(stringValue(response, "service"))
            && intValue(response, "protocol", 0) >= 4;
    }

    private static boolean isSafeDiagnosticResponse(JsonObject response)
    {
        return response != null && booleanValue(response, "ok", false)
            && booleanValue(response, "authenticated", false)
            && booleanValue(response, "readOnly", false)
            && !booleanValue(response, "stateMutation", true)
            && "elite-exiles-runelite-bridge".equals(stringValue(response, "service"))
            && intValue(response, "protocol", 0) >= 4;
    }

    private static boolean booleanValue(JsonObject object, String key, boolean fallback)
    {
