            petCard.add(wrapStyled(booleanValue(pet, "activeBox", false) ? "● MYSTERY PET BOX LIVE" : "No Mystery Pet Box live right now", booleanValue(pet, "activeBox", false) ? GREEN : MUTED, 10, Font.BOLD));
